// === MIGRATED EventProcessor for .NET 8 ===
// Patterns found and replaced:
//   1. Cancellable work loop   (while true → CancellationToken)
//   2. Blocking call interrupt (ManualResetEvent.WaitOne → WaitHandle.WaitAny)
//   3. Thread.Interrupt/Abort  (→ CancellationTokenSource.Cancel)

public class EventProcessor : IDisposable
{
    private readonly ManualResetEventSlim _newEvent = new();
    private readonly Queue<string> _queue = new();
    private readonly CancellationTokenSource _cts = new();
    private Thread? _thread;
    private readonly object _lock = new();

    public void Start()
    {
        _thread = new Thread(RunLoop);
        _thread.Start();
    }

    private void RunLoop()
    {
        var token = _cts.Token;
        while (!token.IsCancellationRequested)
        {
            // Wait for signal OR cancellation — replaces plain WaitOne()
            try
            {
                WaitHandle.WaitAny([_newEvent.WaitHandle, token.WaitHandle]);
            }
            catch (ObjectDisposedException)
            {
                break;
            }

            if (token.IsCancellationRequested)
                break;

            _newEvent.Reset();

            // Drain all queued items (fixes original race condition)
            while (true)
            {
                string? item;
                lock (_lock)
                {
                    if (_queue.Count == 0) break;
                    item = _queue.Dequeue();
                }
                Handle(item);
            }
        }
    }

    public void Enqueue(string item)
    {
        lock (_lock) { _queue.Enqueue(item); }
        _newEvent.Set();
    }

    public void Stop()
    {
        _cts.Cancel();       // signals the token → WaitAny returns
        _thread?.Join(5000); // wait for graceful exit
        // No Thread.Abort fallback — cooperative cancellation only
    }

    public void Dispose()
    {
        Stop();
        _cts.Dispose();
        _newEvent.Dispose();
    }

    private void Handle(string item) { /* ... */ }
}
